const E=MNY,KEY='mny.v1';
let headerRevealTimer=null,headerCloseTimer=null;
let db;try{db=JSON.parse(localStorage.getItem(KEY))}catch{}db=db||{players:[],games:[],active:null};let view='home',undo=[],storageOK=true;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),g=()=>db.active,name=id=>db.players.find(p=>p.id===id)?.name||g()?.guests?.[id]||db.games.map(x=>x.guests?.[id]).find(Boolean)||'Игрок',who=i=>`№${i+1} · ${esc(name(g().seats[i].id))}`,alive=()=>g().seats.map((p,i)=>p.alive?i:null).filter(i=>i!==null);
let databaseMode=false,databaseRevision=0,saveQueue=Promise.resolve(),databaseConflict=false;
function save(){
 const snapshot=JSON.stringify(db);
 if(databaseMode){
  storageOK=true;document.querySelector('.local').textContent='● Сохранение в базу…';
  saveQueue=saveQueue.then(async()=>{if(databaseConflict)throw Error('Данные изменились в другом окне. Экспортируйте текущую копию и обновите страницу.');const response=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:databaseRevision,state:JSON.parse(snapshot)})});if(response.status===409){databaseConflict=true;throw Error('Данные изменились в другом окне. Экспортируйте копию и обновите страницу.')}if(!response.ok)throw Error('Не удалось сохранить в базу. Проверьте, что MNY запущен, и повторите сохранение.');databaseRevision=(await response.json()).revision;storageOK=true;document.querySelector('.local').textContent='● Сохранено в локальную базу';}).catch(error=>{storageOK=false;document.querySelector('.local').textContent='! Изменения не сохранены';toast(error.message)});
 }else{try{localStorage.setItem(KEY,snapshot);storageOK=true}catch{storageOK=false;toast('Не удалось сохранить. Экспортируйте данные.')}document.querySelector('.local').textContent=storageOK?'● Сохранено в браузере':'! Сохранение недоступно'}
}
async function loadDatabase(){
 $('#app').innerHTML='<div class="empty"><h2>Открываем базу клуба…</h2></div>';
 try{const response=await fetch('/api/state',{cache:'no-store'});if(!response.ok)throw Error();const stored=await response.json();databaseRevision=stored.revision;databaseMode=true;const legacy=db;let migrated=false;try{migrated=localStorage.getItem('mny.sqlite.migrated')==='yes'}catch{}
 if(stored.state){db=stored.state;if(!migrated){let added=false;for(const player of legacy.players){if(!db.players.some(p=>p.id===player.id||p.name.toLocaleLowerCase()===player.name.toLocaleLowerCase())){db.players.push(player);added=true}}for(const game of legacy.games){if(!db.games.some(x=>x.id===game.id)){db.games.push(game);added=true}}if(added){save();await saveQueue;if(!storageOK)throw Error()}}}else{save();await saveQueue;if(!storageOK)throw Error()}
 if(migrateRounds(db)){save();await saveQueue;}try{localStorage.setItem('mny.sqlite.migrated','yes')}catch{}render();document.querySelector('.local').textContent='● Локальная база подключена';
 }catch{$('#app').innerHTML='<section class="panel"><h2>Нужно запустить MNY</h2><p>Откройте файл «Запустить MNY.command» в папке проекта, затем обновите страницу. Данные браузера сохранены.</p><button onclick="location.reload()">Повторить подключение</button></section>'}
}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function change(text,fn){undo.push(JSON.stringify(db));if(undo.length>80)undo.shift();fn();storePhaseFrame();if(g())g().log.unshift(`${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})} — ${text}`);save();render()}
function btn(a,t,cls='',extra=''){return `<button data-action="${a}" class="${cls}" ${extra}>${t}</button>`}function options(list,selected,empty=true){return `${empty?'<option value="">Выберите игрока</option>':''}${list.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}`}
function home(){const completed=db.games.length;return `<section class="hero"><div class="host-start"><div class="eyebrow">Mafia New Year · панель ведущей</div><div class="launch-actions">${btn('new','<span class="launch-icon">↗</span><span>Начать партию</span>','primary launch')}${btn('add','<span class="launch-icon">＋</span><span>Добавить игрока</span>','launch launch-secondary')}</div><div class="last-game">${btn('last','↶ Вернуться к последней','text-button',!g()&&!db.games.length?'disabled':'')}</div></div><div class="art" aria-hidden="true"><div class="winter-emblem"><svg viewBox="80 0 260 300" fill="none"><defs><radialGradient id="glass" cx=".32" cy=".25" r=".8"><stop stop-color="#bb647f"/><stop offset=".45" stop-color="#952747"/><stop offset=".85" stop-color="#691c33"/><stop offset="1" stop-color="#471323"/></radialGradient><linearGradient id="rim" x1="120" y1="90" x2="295" y2="250" gradientUnits="userSpaceOnUse"><stop stop-color="#ffffff" stop-opacity=".8"/><stop offset=".5" stop-color="#dab6c3" stop-opacity=".1"/><stop offset="1" stop-color="#dab6c3" stop-opacity=".6"/></linearGradient></defs><path d="M210 0v65" stroke="currentColor" opacity=".5"/><rect x="196" y="65" width="28" height="20" rx="4" fill="#bca5ae"/><path d="M201 69v12m6-12v12m6-12v12m6-12v12" stroke="#f7edf2" opacity=".7"/><circle cx="210" cy="178" r="95" fill="url(#glass)" stroke="url(#rim)" stroke-width="1.5"/><path d="M136 147a79 79 0 0 1 49-43" stroke="#ffffff" stroke-width="8" stroke-linecap="round" opacity=".12"/><path d="M143 126a84 84 0 0 1 23-16" stroke="#ffffff" stroke-width="3" stroke-linecap="round" opacity=".25"/><text x="210" y="192" text-anchor="middle" font-family="Georgia" font-size="43" letter-spacing="3" fill="#fff0f3">MNY</text><path d="M183 211h54" stroke="currentColor" opacity=".35"/><circle cx="86" cy="93" r="2" fill="currentColor" opacity=".5"/><circle cx="326" cy="231" r="2" fill="currentColor" opacity=".5"/></svg></div></div></section><section class="home-stats" aria-label="Обзор клуба и вечера"><article class="panel summary-card"><h2>Список клуба</h2><div class="summary-value"><span class="summary-number">${db.players.length}</span><span class="summary-label">игроков в списке</span></div>${btn('players','<span>Список игроков</span><span aria-hidden="true">↗</span>','summary-link')}</article><article class="panel summary-card"><h2>Этот вечер</h2><div class="summary-value"><span class="summary-number">${completed}</span><span class="summary-label">завершённых партий</span></div>${btn('history','<span>Результаты и статистика</span><span aria-hidden="true">↗</span>','summary-link')}</article></section><div class="home-footer"><span>MAFIA NEW YEAR</span>${btn('export','Сохранить резервную копию ↗')}</div>`}
function playerAvatar(p,cls=''){const photo=typeof p.photo==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(p.photo)?p.photo:null;return `<span class="player-avatar ${cls}">${photo?`<img src="${esc(photo)}" alt="" loading="lazy">`:esc(p.name.slice(0,1).toUpperCase())}</span>`}
function players(){return `<div class="section-top"><div><div class="eyebrow">Участники клуба · ${db.players.length}</div><h1>Игроки</h1></div>${btn('add','＋ Добавить игрока','primary')}</div><section class="player-directory">${db.players.length?db.players.map(p=>`<article class="panel player-profile">${playerAvatar(p)}<div class="profile-text"><h2>${esc(p.name)}</h2><p>${p.fullName?esc(p.fullName):'Имя не указано'}</p></div>${btn('rename','Изменить','profile-edit',`data-id="${p.id}" aria-label="Изменить игрока ${esc(p.name)}"`)}</article>`).join(''):'<div class="panel empty"><h2>Список клуба пока пуст</h2><p>Добавьте игрока: ник, имя и фотографию.</p></div>'}</section>`}
function roleIcon(role){
 const heart='<path fill="currentColor" stroke="none" d="M12 21 3.6 12.7C-2.2 6.8 6.2-.7 12 5.7 17.8-.7 26.2 6.8 20.4 12.7Z"/>';
 const paths={civil:heart,mafia:heart,don:'<path d="M6 15 8 6q.5-2 2.5-.8L12 6l1.5-.8Q15.5 4 16 6l2 9"/><path d="M7 11.5q5 1.5 10 0l.5 3q-5.5 1.5-11 0Z"/><path d="M6 15q-3-.5-5 1.5Q5 20 12 20t11-3.5Q21 14.5 18 15"/><path d="M9.5 6.5 12 8l2.5-1.5"/>',sheriff:'<path d="m12 3 2.7 5.3 5.9.9-4.3 4.1 1 5.9-5.3-2.8-5.3 2.8 1-5.9-4.3-4.1 5.9-.9Z"/><circle cx="12" cy="11.5" r="2.1"/><circle cx="12" cy="2.5" r="1"/><circle cx="21" cy="9" r="1"/><circle cx="17.5" cy="20" r="1"/><circle cx="6.5" cy="20" r="1"/><circle cx="3" cy="9" r="1"/>'};
 return '<svg class="role-icon role-icon-'+role+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[role]+'</svg>'
}
function setup(){const roles=g().setupStep==='roles',count=g().seats.filter(p=>p.id).length;return `<div class="section-top"><div><div class="eyebrow">Подготовка партии</div><h1>${roles?'Назначьте роли':'Рассадка игроков'}</h1></div><div class="setup-steps"><span class="${!roles?'active':''}">01 · Рассадка</span><span class="${roles?'active':''}">02 · Роли</span></div></div><section class="panel seating-panel">${!roles?`<form id="seat-entry" class="nickname-form"><div class="nickname-field"><label for="nickname">Ник игрока</label><input id="nickname" name="nickname" role="combobox" aria-autocomplete="list" aria-controls="nickname-suggestions" aria-expanded="false" placeholder="Введите ник и нажмите Enter" maxlength="60" autocomplete="off" ${count===10?'disabled':''}><div id="nickname-suggestions" class="nickname-suggestions" hidden></div></div><button type="submit" class="primary" ${count===10?'disabled':''}>Добавить ↵</button></form><div class="seating-toolbar"><span class="subtle">${count} / 10 мест занято</span>${btn('shuffle','⤨ Случайная рассадка','',''+(count<10?'disabled':''))}</div>`:`<div class="role-totals">${Object.entries(E.roles).map(([r,title])=>{const n=g().seats.filter(p=>p.role===r).length,target={civil:6,sheriff:1,mafia:2,don:1}[r];return `<span class="role-total ${n===target?'complete':''}" title="${title}" aria-label="${title}: ${n} из ${target}">${roleIcon(r)}<span>${n} / ${target}</span></span>`}).join('')}</div>`}<div class="seating-grid">${g().seats.map((p,i)=>`<article class="seating-card ${p.id?'filled':''}"><div class="seating-name"><span class="num">${i+1}</span><span>${p.id?esc(name(p.id))+(g().guests?.[p.id]?'<small class="guest-label">Гость</small>':''):'<span class="empty-seat">Свободное место</span>'}</span>${!roles&&p.id?btn('unseat','×','unseat',`data-i="${i}" aria-label="Убрать игрока с места ${i+1}"`):''}</div>${roles?`<div class="role-picker">${Object.entries(E.roles).map(([r,title])=>btn('assign-role',roleIcon(r),`role-choice ${p.role===r?'selected':''}`,`data-i="${i}" data-r="${r}" title="${title}" aria-label="Место ${i+1}: ${title}" aria-pressed="${p.role===r}"`)).join('')}</div>`:''}</article>`).join('')}</div><div class="seating-footer"><div class="actions">${roles?btn('seating','← К рассадке'):btn('discard','Отменить подготовку','danger')}${btn('undo','↶ Отменить действие','',''+(!undo.length?'disabled':''))}</div>${roles?btn('start','Начать первый день →','primary',!E.validate(g())?'disabled':''):btn('roles','Подтвердить рассадку →','primary',count<10?'disabled':'')}</div></section>`}
function timer(){return `<section class="panel timer"><div class="timer-peripheral" aria-hidden="true"></div><div class="eyebrow">Таймер ведущего</div><div class="clock" id="clock">0:00:00</div><div class="timer-cue" role="status" aria-live="polite"></div><div class="actions">${btn('timer',g().timer.started?'Пауза':'Старт','primary')}${btn('reset','С нуля')}</div></section>`}
function seat(p,i){const day=g().day,m=p.muteDay===day&&g().phase==='day',future=p.muteDay>day;return `<article class="seat ${!p.alive?'dead':''} ${g().phase==='day'&&g().speaker===i?'current':''}"><div class="seat-top"><span class="num">${i+1}</span><div class="name">${esc(name(p.id))}<div class="role game-role ${E.black(p)?'black':''}" title="${E.roles[p.role]}" aria-label="${E.roles[p.role]}">${roleIcon(p.role)}</div></div><span class="subtle">${p.fouls}/4</span></div>${!p.alive?`<span class="badge">${esc(p.reason)}</span>`:`${m?'<span class="badge">Без речи · можно выставить</span>':''}${future?'<span class="badge">Без речи в следующий день</span>':''}${g().nominated.includes(i)?'<span class="badge">Выставлен</span>':''}${g().spoken.includes(i)?'<span class="badge">Выступил</span>':''}`}<div class="seat-tools">${p.alive?`${btn('foul','＋ Фол','','data-i="'+i+'"')}${btn('unfoul','− Фол','','data-i="'+i+'" '+(!p.fouls?'disabled':''))}${g().phase==='day'?btn('nominate',g().nominated.includes(i)?'Снять кандидатуру':'Выставить','','data-i="'+i+'"'):''}${btn('remove','Удалить','danger','data-i="'+i+'"')}`:btn('restore','Вернуть в игру','','data-i="'+i+'"')}</div></article>`}
function night(){const n=g().nightDraft||{};return `<section class="panel"><h2>Ночные отметки</h2><p>Результаты проверок не отображаются.</p>${[['kill','Жертва мафии'],['sheriff','Проверка шерифа'],['don','Проверка дона']].map(([key,title])=>`<label>${title}</label><select data-night="${key}"><option value="">Не отмечено</option>${alive().map(i=>`<option value="${i}" ${String(n[key])===String(i)?'selected':''}>${who(i)}</option>`).join('')}</select>`).join('')}${btn('dawn','Завершить ночь →','primary full')}</section>`}
function nominationIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 9h4v10H4Z"/><path d="m8 10 4-7c.7-1 2-.5 2 1v5h4.5a2 2 0 0 1 2 2.4l-1 5a3 3 0 0 1-3 2.6H8"/><path d="M2 22h20"/></svg>'}
let selectedNominee=null,recentNominee=null,suppressNomineeClickUntil=0,candidateDrag=null;
function canEditNominees(){return !!g()&&['day','vote'].includes(g().phase)&&g().ballot?.stage!=='result'}
function votingCurrent(){const b=g().ballot;if(!b||b.stage!=='votes')return null;return b.candidates.find(i=>!Object.prototype.hasOwnProperty.call(b.votes,i))??null}
function votingRemaining(){return Math.max(0,(g().ballot.electorate??alive().length)-Object.values(g().ballot.votes).reduce((sum,n)=>sum+Number(n),0))}
function nominationsStrip(){if(!['day','vote','finished'].includes(g().phase))return '';const b=g().ballot,nominees=b?b.candidates:g().nominated.filter(i=>g().seats[i].alive);if(!nominees.length)return '';const active=g().phase==='vote'?votingCurrent():null;return `<div class="nomination-strip" role="group" aria-label="Кандидаты в порядке выставления"><span class="nomination-divider" aria-hidden="true"></span><span class="nomination-title">Голосование:</span><div class="nomination-order">${nominees.map(i=>`<span class="nomination-item ${selectedNominee===i?'selected':''} ${recentNominee===i?'recently-moved':''} ${active===i?'vote-current':''} ${b&&Object.prototype.hasOwnProperty.call(b.votes,i)?'vote-recorded':''}" data-nominee="${i}" draggable="false">${active===i&&(b.castOrder?.length)?btn('vote-back','‹','vote-back',`aria-label="Исправить предыдущие голоса"`):''}${btn('show-nominee-remove',String(i+1),'nomination-chip',`data-i="${i}" title="${esc(name(g().seats[i].id))}" aria-label="Кандидат ${i+1}" aria-expanded="${selectedNominee===i}" aria-keyshortcuts="Alt+ArrowLeft Alt+ArrowRight"`)}${b&&Object.prototype.hasOwnProperty.call(b.votes,i)?`<small class="candidate-votes" aria-label="${b.votes[i]} голосов">${b.votes[i]}</small>`:''}${canEditNominees()?btn('remove-nominee','−','nomination-remove',`data-i="${i}" title="Снять кандидатуру" aria-label="Снять кандидатуру игрока ${i+1}"`):''}</span>`).join('')}</div></div>`}
function votingInline(){const b=g().ballot;if(!b||!['day','vote'].includes(g().phase))return '';if(b.stage==='result')return `<div class="voting-inline vote-summary" role="status">${b.eliminated?.length?'Заголосован '+b.eliminated.map(i=>'№'+(i+1)).join(', ')+' — '+(b.votes[b.eliminated[0]]||0)+' голосов':'Все остались за столом'}${btn('restart-voting','Провести заново','text-button')}</div>`;if(b.stage==='votes'){const current=votingCurrent(),left=votingRemaining();return `<div class="voting-inline"><div class="vote-counts" role="group" aria-label="Голоса за игрока ${current+1}">${Array.from({length:left+1},(_,n)=>btn('cast-vote',String(n),'vote-count',`data-count="${n}" aria-label="Отдать ${n} голосов за игрока ${current+1}"`)).join('')}</div></div>`}return `<div class="voting-inline vote-summary"><span>${b.stage==='speech'?'Равенство · дополнительные речи по 30 секунд':'Повторное равенство'}</span>${b.stage==='speech'?btn('revote','Переголосовать','primary'):btn('lift','Поднять всех','danger')+btn('peace','Оставить всех')}</div>`}
function finishSequentialVote(){const b=g().ballot,tied=E.result(g());if(tied.length===1){E.remove(g(),tied[0],'Заголосован');b.stage='result';b.eliminated=tied;g().phase='day';checkWin()}else{b.candidates=tied;b.stage=b.round===1?'speech':'tie'}}

function nomineePositions(){return new Map(Array.from(document.querySelectorAll?.('.nomination-item')||[]).map(item=>[Number(item.dataset.nominee),item.getBoundingClientRect()]))}
function animateNomineeShift(before){for(const item of document.querySelectorAll?.('.nomination-item')||[]){if(item.classList.contains('dragging'))continue;const previous=before.get(Number(item.dataset.nominee));if(!previous)continue;item.getAnimations?.().forEach(a=>a.cancel());const now=item.getBoundingClientRect();const dx=previous.left-now.left,dy=previous.top-now.top;if((dx||dy)&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){item.getAnimations?.().forEach(a=>a.cancel());item.animate([{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}],{duration:240,easing:'cubic-bezier(.2,.8,.2,1)'})}}}
function applyNomineeOrder(order,moved){if(!canEditNominees()||order.length!==g().nominated.length||new Set(order).size!==order.length||order.some(i=>!g().nominated.includes(i))||order.every((i,k)=>i===g().nominated[k]))return;const before=nomineePositions();recentNominee=moved;change('Изменён порядок выставления',()=>{g().nominated=[...order];if(g().phase==='vote'&&g().ballot){const candidates=new Set(g().ballot.candidates);g().ballot.candidates=order.filter(i=>candidates.has(i))}selectedNominee=null});animateNomineeShift(before);setTimeout(()=>{if(recentNominee===moved){recentNominee=null;document.querySelector(`.nomination-item[data-nominee="${moved}"]`)?.classList?.remove('recently-moved')}},1300)}
function reorderNominees(source,target,after=false){if(!canEditNominees()||source===target||!g().nominated.includes(source)||!g().nominated.includes(target))return;const order=g().nominated.filter(i=>i!==source),position=order.indexOf(target)+(after?1:0);order.splice(position,0,source);applyNomineeOrder(order,source)}
function ballot(){const b=g().ballot,total=Object.values(b.votes).reduce((a,v)=>a+Number(v),0);return `<section class="panel ballot-panel"><div class="eyebrow">${b.round===1?'Голосование':'Переголосование'}</div><h2>${b.stage==='tie'?'Повторное равенство':b.stage==='speech'?'Дополнительные речи':'Голоса города'}</h2>${b.stage==='speech'?'<p>Каждому кандидату — 30 секунд. Таймер управляется вручную.</p>':''}<div class="ballot-candidates">${b.candidates.map(i=>`<div class="ballot-candidate"><span class="num">${i+1}</span><span class="ballot-name">${esc(name(g().seats[i].id))}</span>${b.stage==='votes'?`<input type="number" min="0" max="${alive().length}" step="1" inputmode="numeric" value="${Number(b.votes[i]||0)}" aria-label="Голоса за игрока ${i+1}" data-vote="${i}" ${b.candidates.length===1?'readonly':''}>`:''}</div>`).join('')}</div>${b.stage==='votes'?`<div class="ballot-total">Учтено голосов <strong>${total} / ${alive().length}</strong></div>${b.candidates.length===1?'<p class="subtle">Один кандидат получает все голоса.</p>':''}${btn('count','Подвести итог →','primary full')}`:b.stage==='speech'?btn('revote','Начать переголосование →','primary full'):`<p>Равенство у ${b.candidates.length} кандидатов. Решение принимает ведущая.</p>${btn('lift','Поднять всех кандидатов','danger full')}${btn('peace','Оставить всех · перейти к ночи','full')}${btn('speech','Повторить речи и голосование','full')}`}${btn('cancel-vote','← К выставлению','text-button full')}</section>`}
function votingResult(){const b=g().ballot;if(!b||b.stage!=='result')return '';return `<section class="panel vote-result"><div class="eyebrow">Итог голосования</div><h3>${b.eliminated?.length?'Выбыли: '+b.eliminated.map(i=>'№'+(i+1)).join(', '):'Все остались за столом'}</h3></section>`}
function beginVoting(){const candidates=g().nominated.filter(i=>g().seats[i].alive);g().phase='vote';g().ballot={round:1,stage:'votes',candidates,originalCandidates:[...candidates],electorate:alive().length,castOrder:[],votes:{}};if(candidates.length===1){g().ballot.votes[candidates[0]]=alive().length;finishSequentialVote()}}
function enterNightAfterVote(){g().phase='day';ensurePhaseHistory();storePhaseFrame();if(g().phaseCursor<g().phaseHistory.length-1){propagatePhaseCorrection(g().phaseHistory[g().phaseCursor]);restorePhaseFrame(g().phaseCursor+1)}else{toNight();g().phaseHistory.push(phaseFrame());g().phaseCursor=g().phaseHistory.length-1}}
let justSelectedRole=null;
function hasAssignedRole(p){return p.roleAssigned===true||(p.roleAssigned===undefined&&p.role!=='civil')}
const roleLimits={civil:6,mafia:2,don:1,sheriff:1};
function roleAvailable(role,index){return g().seats.filter((p,i)=>i!==index&&hasAssignedRole(p)&&p.role===role).length<roleLimits[role]}
function fillRemainingRoles(){const pending=g().seats.filter(p=>!hasAssignedRole(p));if(!pending.length)return;const remaining=Object.keys(roleLimits).map(role=>({role,count:roleLimits[role]-g().seats.filter(p=>hasAssignedRole(p)&&p.role===role).length}));if(remaining.some(x=>x.count<0))return;const options=remaining.filter(x=>x.count>0);if(options.length!==1||options[0].count!==pending.length)return;pending.forEach(p=>{p.role=options[0].role;p.roleAssigned=true});g().log.unshift(`Оставшиеся роли назначены автоматически: ${E.roles[options[0].role]} — ${pending.length}`)}
function compactRolePicker(p,i){const assigned=hasAssignedRole(p);return `<div class="compact-role ${justSelectedRole===i?'just-selected':''}" data-role-menu="${i}">${btn('toggle-role',assigned?roleIcon(p.role):'<span aria-hidden="true">＋</span>',`role-trigger ${assigned?'assigned':''}`,`data-i="${i}" aria-label="Роль игрока ${i+1}: ${assigned?E.roles[p.role]:'выбрать'}" title="${assigned?E.roles[p.role]:'Выбрать роль'}" aria-expanded="false"`)}<div class="compact-role-options">${Object.entries(E.roles).filter(([r])=>roleAvailable(r,i)).map(([r,title])=>btn('assign-role',roleIcon(r),`role-choice ${assigned&&p.role===r?'selected':''}`,`data-i="${i}" data-r="${r}" title="${title}" aria-label="Место ${i+1}: ${title}" aria-pressed="${assigned&&p.role===r}"`)).join('')}${assigned?btn('clear-role','×','role-clear',`data-i="${i}" title="Убрать роль" aria-label="Убрать роль игрока ${i+1}"`):''}</div></div>`}
const phaseFields=['phase','day','opener','speaker','spoken','nominated','ballot','nightDraft','seats','nights','winner','ended','setupStep','finishedPhase'];
const clone=value=>JSON.parse(JSON.stringify(value));
function phaseSnapshot(){const snap={};for(const key of phaseFields)if(g()[key]!==undefined)snap[key]=clone(g()[key]);return snap}
function phaseFrame(){const state=phaseSnapshot();return {state,baseline:clone(state)}}
function ensurePhaseHistory(){if(g().phaseHistory?.length)return;const current=phaseFrame();g().phaseHistory=[current];g().phaseCursor=0;
 // Older saves can revisit the most recent recorded night without restarting the game.
 if(g().phase==='day'&&g().nights.length){const record=g().nights[g().nights.length-1],previous=clone(current.state);previous.phase='night';previous.day=record.day;previous.nightDraft={};for(const key of ['kill','sheriff','don','missed'])if(record[key]!==undefined)previous.nightDraft[key]=record[key];previous.nights.pop();if(record.kill!==undefined&&previous.seats[record.kill]?.reason==='Убит ночью'){previous.seats[record.kill].alive=true;previous.seats[record.kill].reason=null;delete previous.seats[record.kill].deathSource}previous.opener=record.opener??(current.state.opener+9)%10;g().phaseHistory.unshift({state:previous,baseline:clone(previous),appliedDraft:clone(previous.nightDraft)});g().phaseCursor=1;}
}
function storePhaseFrame(){if(g()?.phaseHistory?.length)g().phaseHistory[g().phaseCursor].state=phaseSnapshot()}
function restorePhaseFrame(index){const timer=g().timer;for(const key of phaseFields)delete g()[key];Object.assign(g(),clone(g().phaseHistory[index].state));g().phaseCursor=index;g().timer=timer}
function propagatePhaseCorrection(frame){const current=frame.state,old=frame.baseline;
 for(const future of g().phaseHistory.slice(g().phaseCursor+1)){
  for(let i=0;i<current.seats.length;i++){for(const key of ['role','roleAssigned','fouls','technicalFoul','muteDay','mutePending','alive','reason']){if(JSON.stringify(current.seats[i][key])!==JSON.stringify(old.seats[i][key])&&JSON.stringify(future.state.seats[i][key])===JSON.stringify(old.seats[i][key])){future.state.seats[i][key]=current.seats[i][key];future.baseline.seats[i][key]=current.seats[i][key]}}}
 }
 if(current.phase==='night'){
  const before=frame.appliedDraft||{},after=current.nightDraft||{},source='night:'+current.day;
  for(const future of g().phaseHistory.slice(g().phaseCursor+1)){
   for(const state of [future.state,future.baseline]){
    if(before.kill!==after.kill){if(before.kill!==undefined){const p=state.seats[before.kill];if(p.reason==='Убит ночью'&&(!p.deathSource||p.deathSource===source)){p.alive=current.seats[before.kill].alive;p.reason=current.seats[before.kill].reason;delete p.deathSource}}
     if(after.kill!==undefined&&current.seats[after.kill]?.alive){const p=state.seats[after.kill];if(p.alive){p.alive=false;p.reason='Убит ночью';p.deathSource=source}}}
    const record=state.nights.find(n=>n.day===current.day);if(record){for(const key of ['kill','sheriff','don','missed'])delete record[key];Object.assign(record,clone(after))}
    if(state.phase==='day'&&!state.seats[state.opener]?.alive){state.opener=E.nextAlive(state,state.opener);if(!state.seats[state.speaker]?.alive)state.speaker=state.opener}
   }
  }
  frame.appliedDraft=clone(after);
 }
 frame.baseline=clone(current);
}
function finishNight(){const n={...g().nightDraft,day:g().day,opener:g().opener};g().nights.push(n);g().log.unshift(`Ночь: жертва ${n.kill!==undefined?'№'+(Number(n.kill)+1):n.missed?'промах':'—'}, шериф ${n.sheriff!==undefined?'№'+(Number(n.sheriff)+1):'—'}, дон ${n.don!==undefined?'№'+(Number(n.don)+1):'—'}`);if(n.kill!==undefined){E.remove(g(),Number(n.kill),'Убит ночью');g().seats[Number(n.kill)].deathSource='night:'+g().day}checkWin();if(g().phase!=='finished')E.startDay(g())}
function movePhase(direction){if(direction>0&&g().phase==='vote')return toast('Сначала завершите голосование или вернитесь к выставлению');if(direction>0&&g().phase==='day'&&!g().ballot&&g().nominated.some(i=>g().seats[i].alive)){change('Началось голосование',beginVoting);return}ensurePhaseHistory();if(direction<0){if(g().phaseCursor===0)return;change('Возврат к предыдущей фазе',()=>{storePhaseFrame();restorePhaseFrame(g().phaseCursor-1)});return}
 if(g().phase==='setup'&&(!E.validate(g())||!g().seats.every(hasAssignedRole)))return toast('Сначала назначьте все роли');
 change('Переход к следующей фазе',()=>{storePhaseFrame();const frame=g().phaseHistory[g().phaseCursor];if(g().phaseCursor<g().phaseHistory.length-1){propagatePhaseCorrection(frame);restorePhaseFrame(g().phaseCursor+1);return}if(g().phase==='setup')E.startDay(g());else if(['day','vote'].includes(g().phase))toNight();else if(g().phase==='night'){frame.appliedDraft=clone(g().nightDraft||{});finishNight()}else return;g().phaseHistory.push(phaseFrame());g().phaseCursor=g().phaseHistory.length-1;});
}
function phaseSwitch(){const isNight=g().phase==='night'||g().phase==='setup',ready=g().phase!=='vote'&&(g().phase!=='setup'||(E.validate(g())&&g().seats.every(hasAssignedRole))),back=(g().phaseCursor??0)>0||(!g().phaseHistory&&g().phase==='day'&&g().nights.length>0);const icon=isNight?'<path d="M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z"/>':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>';return `<div class="phase-arrows" role="group" aria-label="Смена дня и ночи">${btn('phase-back','←','phase-arrow',`title="Вернуться к предыдущей фазе" aria-label="Предыдущая фаза" ${!back?'disabled':''}`)}<span class="phase-indicator ${isNight?'is-night':'is-day'}" role="img" aria-label="${isNight?'Ночь':'День'}" title="${isNight?'Ночь':'День'}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon}</svg></span>${btn('phase-forward','→','phase-arrow',`title="Перейти к следующей фазе" aria-label="Следующая фаза" ${!ready?'disabled':''}`)}</div>`}
function migrateRounds(state){let changed=false;for(const game of [...state.games,...(state.active?[state.active]:[])]){if(game.roundVersion===2)continue;game.day=game.phase==='setup'?-1:game.day-1;game.seats.forEach(p=>{if(p.muteDay!==null&&p.muteDay!==undefined)p.muteDay--});game.nights.forEach(n=>n.day--);game.roundVersion=2;changed=true}return changed}
function foulControl(p,i){const muted=p.alive&&p.fouls===3&&p.muteDay===g().day&&['day','vote'].includes(g().phase);return `<div class="foul-control ${p.fouls===3?'warning':''}">${muted?'<span class="mute-indicator" role="img" aria-label="Без речи в этот круг" title="Без речи в этот круг"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><path d="M12 15a3 3 0 0 0 3-3V5a3 3 0 0 0-6 0v4m-3 1v2a6 6 0 0 0 10 4m2-5v1M12 18v4m-4 0h8M3 3l18 18"/></svg></span>':''}${btn('cycle-foul',Array.from({length:3},(_,k)=>`<span class="foul-dot ${k<p.fouls?'filled':''}"></span>`).join(''),'foul-meter foul-cycle',`data-i="${i}" aria-label="Фолы игрока ${i+1}: ${p.fouls} из 3. Добавить фол" ${!p.alive||g().phase==='finished'?'disabled':''}`)}${btn('technical-foul','Т',`technical-foul ${p.technicalFoul?'active':''}`,`data-i="${i}" aria-label="Технический фол игрока ${i+1}" aria-pressed="${!!p.technicalFoul}" title="${p.technicalFoul?'Тех. фол получен · нажмите, чтобы исправить':'Технический фол'}" ${!p.alive||g().phase==='finished'?'disabled':''}`)}${p.mutePending?`<div class="foul-choice" role="group" aria-label="Когда пропустить речь игроку ${i+1}">${btn('choose-mute','Этот круг','',`data-i="${i}" data-next="0"`)}${btn('choose-mute','Следующий','',`data-i="${i}" data-next="1"`)}</div>`:''}</div>`}

function nightBoard(){const draft=g().nightDraft||{};return `<section class="panel night-board"><h2>Действия ночи</h2>${[['kill','Отстрел'],['sheriff','Проверка шерифа'],['don','Проверка дона']].map(([key,title])=>`<div class="night-action night-${key}"><h3>${title}</h3><div class="night-numbers">${g().seats.map((p,i)=>btn('night-mark',String(i+1),`night-number ${draft[key]===i?'marked':''}`,`data-key="${key}" data-number="${i}" aria-label="${title}: игрок ${i+1}" aria-pressed="${draft[key]===i}" ${key==='kill'&&!p.alive?'disabled':''}`)).join('')}${key==='kill'?btn('night-miss','×',`night-miss ${draft.missed?'marked':''}`,`title="Промах" aria-label="Промах" aria-pressed="${!!draft.missed}"`):''}</div></div>`).join('')}</section>`}
function firstKilled(){return g().nights.find(n=>Number.isInteger(n.kill)&&n.kill>=0&&n.kill<10)?.kill??null}
let editingBestMove=false;
function bestMoveBoard(){const owner=firstKilled();return owner===null?'':bestMoveInline(owner)}
function bestMoveInline(i){if(i!==firstKilled())return '';const picked=g().bestMoves?.[i]||[],editing=editingBestMove||picked.length<3;return `<span class="best-move-inline"><span class="best-move-label">ЛХ</span>${editing?`<span class="best-move-numbers" role="group" aria-label="Лучший ход первоубиенного">${g().seats.map((p,n)=>btn('best-move',String(n+1),`best-move-number ${picked.includes(n)?'marked':''}`,`data-i="${n}" aria-label="ЛХ: игрок ${n+1}" aria-pressed="${picked.includes(n)}" ${picked.length>=3&&!picked.includes(n)?'disabled':''}`)).join('')}</span>${picked.length===3?btn('close-best-move','Готово','best-move-edit'):''}`:`<span class="best-move-picked">${picked.map(n=>`<span>${n+1}</span>`).join('')}</span>${btn('edit-best-move','✎','best-move-edit','aria-label="Изменить лучший ход" title="Изменить ЛХ"')}`}</span>`}

function removalBar(){return `<div class="removal-bar" role="group" aria-label="Удаление игроков"><span class="removal-bar-icon" title="Удаление" aria-label="Удаление">!</span><div class="removal-numbers">${g().seats.map((p,i)=>btn(p.alive?'remove':'restore',String(i+1),`removal-number ${!p.alive?(/^Удалён/.test(p.reason||'')?'removed':'eliminated'):''}`,`data-i="${i}" aria-label="${p.alive?'Удалить':'Вернуть'} игрока ${i+1}" title="${p.alive?'Удалить игрока '+(i+1):esc(p.reason||'Выбыл')+' · вернуть игрока'}" aria-pressed="${!p.alive}"`)).join('')}</div></div>`}
function initialNight(){const phase=g().phase==='finished'?(g().finishedPhase||'day'):g().phase;return `<div class="section-top"><div class="phase-title"><h1>${phase==='setup'?'Начальная ночь':phase==='night'?'Ночь':'День'}</h1>${nominationsStrip()}</div><div class="actions">${g().phase==='day'&&!g().ballot?btn('voting','Начать голосование','primary vote-start',g().nominated.some(i=>g().seats[i].alive)?'':'disabled'):g().phase==='vote'?btn('cancel-vote','К выставлению','text-button'):''}${g().phase==='finished'?'':phaseSwitch()}${g().phase==='setup'?btn('seating','← Изменить рассадку'):''}${btn('undo','↶ Отменить','',''+(!undo.length?'disabled':''))}</div></div>${votingInline()}<div class="layout host-layout"><section class="host-roster-section"><div class="panel host-table"><div class="host-table-heading"><span>${['setup','night'].includes(phase)?'Место · игрок · роль':'Место · игрок'}</span><span class="fouls-heading"><span class="regular-fouls-heading">Фолы</span><span class="technical-foul-heading">Тех.<br>фол</span></span></div><div class="host-roster">${g().seats.map((p,i)=>`<article class="host-player-row ${!p.alive?'player-out':''}"><div class="host-player-name"><span class="player-position"><span class="num">${i+1}</span>${['day','vote'].includes(g().phase)&&g().opener===i?`<span class="day-opener" role="img" aria-label="Открывает круг" title="Открывает круг"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M6 10v2a6 6 0 0 0 12 0v-2M12 18v4m-4 0h8"/></svg></span>`:''}</span><strong>${esc(name(p.id))}</strong>${g().phase==='setup'?compactRolePicker(p,i):phase==='night'?`<span class="role-trigger assigned night-role" role="img" aria-label="${E.roles[p.role]}" title="${E.roles[p.role]}">${roleIcon(p.role)}</span>`:''}${g().guests?.[p.id]?'<small class="guest-label">Гость</small>':''}${bestMoveInline(i)}</div><div class="player-row-actions">${g().phase==='day'&&p.alive?btn('nominate',nominationIcon(),`nominate-button ${g().nominated.includes(i)?'already-nominated':''}`,`data-i="${i}" title="${g().nominated.includes(i)?'Уже выставлен':'Выставить на голосование'}" aria-label="Выставить игрока ${i+1}" ${g().nominated.includes(i)?'disabled':''}`):''}${foulControl(p,i)}</div></article>`).join('')}</div></div><div class="panel elimination-panel">${removalBar()}</div><div class="game-restart-actions">${btn('restart-game','↻ Начать игру заново','text-button')}</div></section><aside class="side">${g().phase==='finished'?finished():timer()}${phase==='night'?`<fieldset class="night-context" ${g().phase==='finished'?'disabled':''}>${nightBoard()}</fieldset>`:''}</aside></div>`}
function game(){if(g().phase==='setup'&&g().setupStep!=='roles')return setup();return initialNight()}
function finished(){return `<section class="panel victory-card" role="status"><div class="eyebrow">Партия завершена</div><h2 class="winner">${g().winner==='red'?'Победа города':g().winner==='black'?'Победа мафии':'Без результата'}</h2><div class="victory-actions">${btn('closegame','К обзору вечера','primary')}${btn('history','Посмотреть статистику')}${btn('restart-game','↻ Начать игру заново','text-button')}${btn('undo','↶ Отменить итог','',''+(!undo.length?'disabled':''))}</div></section>`}

function history(){const stats={};for(const game of db.games)for(const p of game.seats){const s=stats[p.id]??={games:0,wins:0};s.games++;if(game.winner&&(E.black(p)?game.winner==='black':game.winner==='red'))s.wins++}return `<div class="section-top"><div><div class="eyebrow">История и результаты</div><h1>Статистика вечера</h1></div><div class="actions">${btn('export','Экспорт JSON')}${btn('import','Импорт копии')}</div></div><section class="panel"><h2>Игроки</h2>${Object.keys(stats).length?`<table><thead><tr><th>Игрок</th><th>Партий</th><th>Побед</th><th>Поражений</th></tr></thead><tbody>${Object.entries(stats).map(([id,s])=>`<tr><td>${esc(name(id))}</td><td>${s.games}</td><td>${s.wins}</td><td>${db.games.filter(x=>x.winner&&x.seats.some(p=>p.id===id)).length-s.wins}</td></tr>`).join('')}</tbody></table>`:'<p>Здесь появятся результаты завершённых партий.</p>'}</section><section class="panel" style="margin-top:20px"><h2>Партии</h2>${db.games.map(x=>`<details><summary class="row">${new Date(x.created).toLocaleString('ru-RU')} · ${x.winner==='red'?'Победа города':x.winner==='black'?'Победа мафии':'Без результата'}</summary>${x.seats.map(p=>`<div class="row"><span class="num">${p.number}</span><span class="grow">${esc(name(p.id))}</span><span>${E.roles[p.role]}</span></div>`).join('')}<div class="log">${x.log.map(l=>`<div>${esc(l)}</div>`).join('')}</div></details>`).join('')||'<p>Пока нет завершённых партий.</p>'}</section>`}
function render(){if(view==='game'&&!g())view='home';syncGameHeader();$('#app').innerHTML=view==='home'?home():view==='players'?players():view==='history'?history():game();tick()}
function modal(html){$('#dialog').innerHTML=html;$('#dialog').showModal()}
function add(id){
 const p=db.players.find(p=>p.id===id);let photo=p?.photo||'',photoVersion=0;
 modal(`<div class="eyebrow">Карточка клуба</div><h2>${p?'Изменить игрока':'Новый игрок'}</h2><form id="playerform"><div class="profile-photo-editor"><div id="photo-preview">${playerAvatar(p||{name:'?'})}</div><div><label class="photo-upload" for="playerphoto">Загрузить фото</label><input type="file" id="playerphoto" accept="image/jpeg,image/png,image/webp" class="photo-file"><small>JPG, PNG или WebP · до 15 МБ</small><small>Сохраняется целиком, без обрезки</small><button type="button" id="remove-photo" class="text-button" ${!photo?'hidden':''}>Убрать фото</button></div></div><label for="playername">Ник</label><input id="playername" required maxlength="60" value="${esc(p?.name||'')}" placeholder="Игровой ник" autocomplete="off" autofocus><label for="playerfullname">Имя</label><input id="playerfullname" required maxlength="100" value="${esc(p?.fullName||'')}" placeholder="Как зовут игрока" autocomplete="off"><p id="photo-status" class="photo-status" role="status"></p><div class="actions profile-form-actions"><button id="save-profile" class="primary" type="submit">Сохранить игрока</button><button type="button" data-action="cancel">Отмена</button></div></form>`);
 const preview=()=>{$('#photo-preview').innerHTML=playerAvatar({name:$('#playername').value.trim()||'?',photo});$('#remove-photo').hidden=!photo};
 $('#playername').oninput=preview;
 $('#remove-photo').onclick=()=>{photoVersion++;photo='';$('#playerphoto').value='';$('#photo-status').textContent='';$('#save-profile').disabled=false;preview()};
 $('#playerphoto').onchange=async e=>{const file=e.target.files[0];if(!file)return;const version=++photoVersion;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){$('#photo-status').textContent='Выберите JPG, PNG или WebP.';return}if(file.size>15*1024*1024){$('#photo-status').textContent='Выберите фото размером до 15 МБ.';return}$('#save-profile').disabled=true;$('#photo-status').textContent='Подготовка фото…';let bitmap;try{bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fffcf7';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);if(version!==photoVersion)return;photo=canvas.toDataURL('image/jpeg',.92);preview();$('#photo-status').textContent=`Фото готово · ${canvas.width} × ${canvas.height}`}catch{if(version===photoVersion)$('#photo-status').textContent='Не удалось открыть фото. Попробуйте другой файл.'}finally{bitmap?.close();if(version===photoVersion)$('#save-profile').disabled=false}};
 $('#playerform').onsubmit=e=>{e.preventDefault();if($('#save-profile').disabled)return;const nick=$('#playername').value.trim(),fullName=$('#playerfullname').value.trim();if(!nick||!fullName)return;if(db.players.some(x=>x.id!==id&&x.name.toLocaleLowerCase()===nick.toLocaleLowerCase()))return toast('Игрок с таким ником уже есть');change('Карточка игрока сохранена',()=>{if(p)Object.assign(p,{name:nick,fullName,photo});else db.players.push({id:crypto.randomUUID(),name:nick,fullName,photo})});if(storageOK)$('#dialog').close()};
}
function toNight(){g().phase='night';g().nightDraft={}}
function checkWin(){const w=E.winner(g());if(w)end(w)}
function end(w){g().finishedPhase=g().phase==='night'?'night':'day';g().winner=w;g().phase='finished';g().timer.started=null;g().ended=new Date().toISOString();db.games=db.games.filter(x=>x.id!==g().id);db.games.push(JSON.parse(JSON.stringify(g())));}
function timerWarning(seconds,running){return !!running&&seconds%60>=50&&seconds%60<55}
