function nicknameSuggestions(){const input=$('#nickname'),box=$('#nickname-suggestions');if(!input||!box)return;const text=input.value.trim(),query=text.toLocaleLowerCase();const matches=text?db.players.filter(p=>p.name.toLocaleLowerCase().includes(query)&&!g().seats.some(s=>s.id===p.id)):[];box.hidden=!text;input.setAttribute?.('aria-expanded',String(!!text));box.innerHTML=!text?'':matches.length?matches.map(p=>btn('pick-player',`<span>${esc(p.name)}</span><small>${esc(p.fullName||'Игрок клуба')}</small>`,'nickname-option',`data-id="${p.id}"`)).join(''):btn('guest',`<span>Гость · ${esc(text)}</span><small>Только в этой партии</small>`,'nickname-option');}
function seatPlayer(id,guest){if(!g()||g().phase!=='setup'||g().setupStep==='roles')return;const index=g().seats.findIndex(p=>!p.id),nick=$('#nickname')?.value.trim();if(index<0)return;const player=guest?null:db.players.find(p=>p.id===id);if(!guest&&!player)return;if(guest&&!nick)return;const label=guest?nick:player.name;if(g().seats.some(p=>p.id&&name(p.id).toLocaleLowerCase()===label.toLocaleLowerCase()))return toast('Этот игрок уже за столом');change(`Добавлен ${guest?'гость':'игрок'} на место №${index+1}`,()=>{let chosen=id;if(guest){chosen='guest:'+crypto.randomUUID();g().guests??={};g().guests[chosen]=nick}g().seats[index].id=chosen});$('#nickname')?.focus?.();}
