document.addEventListener('pointermove',e=>{const drag=candidateDrag;if(!drag||e.pointerId!==drag.pointerId)return;if(!drag.active&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<5)return;e.preventDefault();if(!drag.active){drag.active=true;drag.container.setPointerCapture(drag.pointerId);selectedNominee=null;drag.item.classList.remove('selected');drag.item.classList.add('dragging');drag.ghost=drag.button.cloneNode(true);drag.ghost.removeAttribute('data-action');drag.ghost.removeAttribute('data-i');drag.ghost.setAttribute('aria-hidden','true');drag.ghost.classList.add('candidate-drag-ghost');drag.ghost.style.width=drag.rect.width+'px';drag.ghost.style.height=drag.rect.height+'px';document.body.append(drag.ghost)}drag.ghost.style.left=(e.clientX-(drag.startX-drag.rect.left))+'px';drag.ghost.style.top=(e.clientY-(drag.startY-drag.rect.top))+'px';const items=Array.from(drag.container.querySelectorAll('.nomination-item')).filter(item=>item!==drag.item);const beforeItem=items.find(item=>{const parent=drag.container.getBoundingClientRect(),r={top:parent.top+item.offsetTop,left:parent.left+item.offsetLeft,bottom:parent.top+item.offsetTop+item.offsetHeight,width:item.offsetWidth};return e.clientY<r.top||(e.clientY<=r.bottom&&e.clientX<r.left+r.width/2)})||null;if(drag.item.nextElementSibling!==beforeItem){const before=nomineePositions();drag.container.insertBefore(drag.item,beforeItem);animateNomineeShift(before)}} ,{passive:false});
document.addEventListener('pointerup',e=>{if(candidateDrag?.pointerId!==e.pointerId)return;if(candidateDrag.active)e.preventDefault();endCandidateDrag()});
document.addEventListener('pointercancel',()=>endCandidateDrag(true));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&candidateDrag){e.preventDefault();endCandidateDrag(true)}});
document.addEventListener('keydown',e=>{const button=e.target.closest?.('[data-action="show-nominee-remove"]');if(!button||!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key)||!canEditNominees())return;e.preventDefault();const source=Number(button.dataset.i),position=g().nominated.indexOf(source),next=position+(e.key==='ArrowRight'?1:-1);if(next<0||next>=g().nominated.length)return;reorderNominees(source,g().nominated[next],e.key==='ArrowRight');document.querySelector(`.nomination-chip[data-i="${source}"]`)?.focus()});

document.addEventListener('lostpointercapture',e=>{if(candidateDrag?.pointerId===e.pointerId)endCandidateDrag(true)});


function syncGameHeader(){const inGame=view==='game'&&!!g();document.body?.classList?.toggle('game-mode',inGame);if(!inGame){clearTimeout(headerRevealTimer);clearTimeout(headerCloseTimer);setGameHeader(false)}}
function setGameHeader(open){const header=$('header');header?.classList?.toggle('game-header-open',open);document.body?.classList?.toggle('game-header-revealed',open&&view==='game');if(open&&header?.getBoundingClientRect)document.body?.style?.setProperty('--game-header-height',header.getBoundingClientRect().height+'px');$('.garland-trigger')?.setAttribute?.('aria-expanded',String(open));for(const node of header?.querySelectorAll?.('a,nav button')||[])if(open||view!=='game')node.removeAttribute('tabindex');else node.setAttribute('tabindex','-1')}
const gameHeader=$('header'),garlandTrigger=$('.garland-trigger');
garlandTrigger?.addEventListener?.('pointerenter',()=>{if(view!=='game')return;clearTimeout(headerCloseTimer);clearTimeout(headerRevealTimer);headerRevealTimer=setTimeout(()=>{if(view==='game')setGameHeader(true)},700)});
garlandTrigger?.addEventListener?.('pointerleave',()=>clearTimeout(headerRevealTimer));
garlandTrigger?.addEventListener?.('click',()=>{if(view==='game'){clearTimeout(headerRevealTimer);setGameHeader(true)}});
gameHeader?.addEventListener?.('pointerenter',()=>clearTimeout(headerCloseTimer));
gameHeader?.addEventListener?.('pointerleave',()=>{clearTimeout(headerRevealTimer);if(!gameHeader.matches(':focus-within'))headerCloseTimer=setTimeout(()=>setGameHeader(false),200)});
gameHeader?.addEventListener?.('focusout',e=>{if(!gameHeader.contains(e.relatedTarget))setGameHeader(false)});
gameHeader?.addEventListener?.('keydown',e=>{if(e.key==='Escape'){setGameHeader(false);garlandTrigger.focus()}});
